            "kjv": "Now therefore hold him not guiltless: for thou [art] a wise man, and knowest what thou oughtest to do unto him; but his hoar head bring thou down to the grave with blood. David’s Reign and Death",
            "asv": "Now therefore hold him not guiltless, for thou art a wise man; and thou wilt know what thou oughtest to do unto him, and thou shalt bring his hoar head down to Sheol with blood. David’s Reign and Death",
            "niv": "But now, do not consider him innocent. You are a man of wisdom; you will know what to do to him. Bring his gray head down to the grave in blood.\"",
            "esv": "Now therefore do not hold him guiltless, for you are a wise man. You will know what you ought to do to him, and you shall bring his gray head down with blood to Sheol.” The Death of David"
